import assert from "node:assert/strict";
import fs from "node:fs";
import test from "node:test";

import { plan } from "./model.mjs";

const night = JSON.parse(fs.readFileSync(new URL("./night.json", import.meta.url)));
const close = (actual, expected, tolerance = 1e-7) => {
  assert.ok(
    Math.abs(actual - expected) <= tolerance,
    `expected ${expected}, got ${actual}`,
  );
};

function caps(buildingKw) {
  return buildingKw.map((load) =>
    Math.max(0, Math.min(night.chargerKw, night.siteLimitKw - load)),
  );
}

function batteryGain(scenario, bus, efficiency = night.efficiency) {
  let acEnergy = 0;
  for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
    acEnergy += scenario.acKw[slot] * night.slotHours;
  }
  return acEnergy * efficiency;
}

function assertPhysical(scenario, buildingKw, efficiency = night.efficiency) {
  assert.equal(scenario.acKw.length, night.slotStart.length);
  const limits = caps(buildingKw);

  scenario.acKw.forEach((power, slot) => {
    assert.ok(power >= 0);
    assert.ok(power <= limits[slot] + 1e-7);
    assert.ok(buildingKw[slot] + power <= night.siteLimitKw + 1e-7);
    const inWindow = night.buses.some(
      (bus) => slot >= bus.fromSlot && slot < bus.untilSlot,
    );
    if (!inWindow) close(power, 0);
  });

  for (const bus of night.buses) {
    let acEnergy = 0;
    for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
      acEnergy += scenario.acKw[slot] * night.slotHours;
    }
    const endKwh = bus.startKwh + acEnergy * efficiency;
    assert.ok(endKwh <= bus.capacityKwh + 1e-7);
    assert.ok(endKwh <= Math.max(bus.requiredKwh, bus.startKwh) + 1e-7);
  }
}

