import {existsSync, readFileSync} from "node:fs";

const read = (path) => JSON.parse(readFileSync(path));
const toMinutes = (time) => {
  const [hours, minutes] = String(time).split(":").map(Number);
  return hours * 60 + minutes;
};

const plan = read("shift-plan.json");
const night = read("night.json");
const recordPaths = ["operations/cold-cycle.json", "operations/duty-2340.json"].filter(existsSync);
const records = recordPaths.map(read);
const record = process.argv[2]
  ? read(process.argv[2])
  : records.sort((a, b) => toMinutes(b.time) - toMinutes(a.time))[0];

const limits = record.limitsKw ?? record.samples.map(
  (sample) => (sample.acMeterEndKwh - sample.acMeterStartKwh) * 60 / sample.minutes,
);
const actual = limits.map((limit, index) => Math.min(limit, plan.acKw[index]));
const departureKwh = night.buses.map((bus) => {
  let acKwh = 0;
  for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
    acKwh += actual[slot] * night.slotHours;
  }
  return bus.startKwh + acKwh * night.efficiency;
});

console.log(JSON.stringify({
  run: record.run,
  time: record.time,
  limits,
  actual,
  withinLimits: plan.acKw.every((power, index) => power <= limits[index]),
  departureKwh,
}));

